diff --git a/src/path.mjs b/src/path.mjs
index 3f0e871..3b95706 100644
--- a/src/path.mjs
+++ b/src/path.mjs
@@ -1,5 +1,20 @@
-import { resolve } from "node:path";
+import { isAbsolute, relative, resolve, sep } from "node:path";

 export function resolveChild(root, child) {
-  return resolve(root, child);
+  if (isAbsolute(child)) {
+    throw new Error("Child path must be relative to root");
+  }
+
+  const resolved = resolve(root, child);
+  const relativePath = relative(root, resolved);
+  if (
+    relativePath === "" ||
+    relativePath === ".." ||
+    relativePath.startsWith(`..${sep}`) ||
+    isAbsolute(relativePath)
+  ) {
+    throw new Error("Child path must resolve inside root");
+  }
+
+  return resolved;
 }

diff --git a/src/cache.mjs b/src/cache.mjs
index 2fe3ea5..e66d359 100644
--- a/src/cache.mjs
+++ b/src/cache.mjs
@@ -5,12 +5,18 @@ export function createCache(load, { ttlMs, now }) {
   return {
     async get(key) {
       const entry = entries.get(key);
+      if (entry?.pending) return entry.pending;
       if (isFresh(entry, now())) return entry.value;
-      const pending = load(key);
-      entries.set(key, { value: pending, expiresAt: now() + ttlMs });
-      const value = await pending;
-      entries.set(key, { value, expiresAt: now() + ttlMs });
-      return value;
+      const pending = Promise.resolve(load(key));
+      entries.set(key, { pending });
+      try {
+        const value = await pending;
+        entries.set(key, { value, expiresAt: now() + ttlMs });
+        return value;
+      } catch (error) {
+        entries.delete(key);
+        throw error;
+      }
     },
   };
 }
diff --git a/src/entry.mjs b/src/entry.mjs
index 2797db0..3f35ab1 100644
--- a/src/entry.mjs
+++ b/src/entry.mjs
@@ -1,3 +1,3 @@
 export function isFresh(entry, now) {
-  return Boolean(entry) && entry.expiresAt >= now;
+  return Boolean(entry) && entry.expiresAt > now;
 }
